import React, { useState, useEffect, useContext, useRef } from 'react';
import axios from 'axios';
import { Search, Users, Book, Calendar, Globe, TrendingUp, MessageCircle, Bell, Check, X, Send, Trash2, Home, User } from "lucide-react";

import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import { AuthContext } from '../context/AuthContext';

const styles = {
  body: {
    height: "100vh",
    backgroundColor: "#f5ede6",
    color: "#4b3b34",
    fontFamily: "Arial, sans-serif",
    margin: 0,
    padding: 0,
    overflow: "hidden",
    display: "flex",
    flexDirection: "column",
  },
  navbar: {
    backgroundColor: "#4b3b34",
    color: "#f5ede6",
    boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
    padding: "1rem 2rem",
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    top: 0,
    left: 0,
    right: 0,
    height: "50px",
  },
  logoText: {
    fontWeight: "bold",
    fontSize: "2rem",
    color: "#f5ede6",
  },
  navLink: {
    color: "#f5ede6",
    textDecoration: "none",
    cursor: "pointer",
    transition: "color 0.2s ease",
  },
  navActions: {
    display: "flex",
    alignItems: "center",
    gap: "1rem",
  },
  bellBtn: {
    backgroundColor: "transparent",
    color: "#ffffff",
    fontSize: "16px",
    padding: "0.75rem",
    borderRadius: "8px",
    border: "2px solid #EDE3DB",
    cursor: "pointer",
    position: "relative",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
  },
  badge: {
    position: "absolute",
    top: "-5px",
    right: "-5px",
    backgroundColor: "#ef4444",
    color: "white",
    borderRadius: "50%",
    width: "20px",
    height: "20px",
    fontSize: "12px",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    fontWeight: "bold",
  },
  notificationDropdown: {
    position: "absolute",
    top: "80px",
    right: "20px",
    backgroundColor: "#fff",
    borderRadius: "12px",
    boxShadow: "0 4px 20px rgba(0,0,0,0.15)",
    width: "400px",
    maxHeight: "500px",
    overflowY: "auto",
    zIndex: 1000,
  },
  notificationHeader: {
    padding: "1rem 1.5rem",
    borderBottom: "1px solid #e0d5cc",
    fontWeight: "bold",
    fontSize: "1.1rem",
    color: "#4b3b34",
  },
  notificationSectionTitle: {
    padding: '0.5rem 1.5rem 0.25rem',
    fontSize: '0.8rem',
    fontWeight: 'bold',
    color: '#6a5b53',
    textTransform: 'uppercase',
    marginTop: '0.5rem'
  },
  notificationItem: {
    padding: "1rem 1.5rem",
    borderBottom: "1px solid #f0f0f0",
  },
  notificationName: {
    fontWeight: "600",
    color: "#4b3b34",
    marginBottom: "0.5rem",
  },
  notificationSkills: {
    fontSize: "0.9rem",
    color: "#6a5b53",
    marginBottom: "0.75rem",
  },
  notificationActions: {
    display: "flex",
    gap: "0.5rem",
  },
  acceptBtn: {
    backgroundColor: "#22c55e",
    color: "white",
    border: "none",
    padding: "0.5rem 1rem",
    borderRadius: "6px",
    cursor: "pointer",
    fontSize: "0.9rem",
    display: "flex",
    alignItems: "center",
    gap: "0.25rem",
  },
  rejectBtn: {
    backgroundColor: "#ef4444",
    color: "white",
    border: "none",
    padding: "0.5rem 1rem",
    borderRadius: "6px",
    cursor: "pointer",
    fontSize: "0.9rem",
    display: "flex",
    alignItems: "center",
    gap: "0.25rem",
  },
  chatBtn: {
    backgroundColor: "transparent",
    color: "#ffffff",
    fontSize: "16px",
    padding: "0.75rem",
    borderRadius: "8px",
    border: "2px solid #EDE3DB",
    cursor: "pointer",
    position: "relative",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
  },
  profileBtn: {
    backgroundColor: "transparent",
    color: '#EDE3DB',
    textDecoration: 'none',
    transition: 'color 0.3s',
    border: '2px solid #EDE3DB',
    borderRadius: '0.5rem',
    padding: "0.75rem 1.5rem",
    cursor: 'pointer',
    fontSize: '1rem'
  },
  main: {
    flex: 1,
    overflowY: "auto",
    padding: "2rem 2rem 6rem",
    maxWidth: "1200px",
    margin: "0 auto",
    height: 0,
    minHeight: 0,
    scrollbarWidth: 'none',
    msOverflowStyle: 'none'
  },
  hero: {
    textAlign: "center",
    marginBottom: "3rem",
    marginTop: '2rem'
  },
  heading: {
    fontSize: "2.7rem",
    fontWeight: "bold",
    marginTop: '0',
    marginBottom: "1rem",
    color: "#4b3b34",
  },
  subHeading: {
    color: "#6a5b53",
    fontSize: "1.3rem",
    marginBottom: "2rem",
    maxWidth: "600px",
    margin: "0 auto 2rem",
  },
  searchContainer: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    marginBottom: "3rem",
  },
  searchBox: {
    display: "flex",
    alignItems: "center",
    backgroundColor: "#fff",
    borderRadius: "12px",
    boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
    border: "2px solid #e0d5cc",
    padding: "1rem 1.5rem",
    width: "100%",
    maxWidth: "900px",
    transition: "box-shadow 0.2s ease, border-color 0.2s ease",
  },
  searchInput: {
    flex: 1,
    border: "none",
    outline: "none",
    fontSize: "1.2rem",
    backgroundColor: "transparent",
    marginLeft: "0.75rem",
  },
  statsGrid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(250px, 1fr))",
    gap: "1.5rem",
    marginBottom: "3rem",
  },
  statCard: {
    backgroundColor: "#fff",
    borderRadius: "12px",
    boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
    padding: "2rem",
    textAlign: "center",
    transition: "transform 0.2s ease, box-shadow 0.2s ease",
  },
  statValue: {
    fontSize: "2rem",
    fontWeight: "bold",
    color: "#4b3b34",
    marginBottom: "0.5rem",
  },
  statLabel: {
    fontSize: "1.2rem",
    color: "#6a5b53",
    marginBottom: "0.5rem",
  },
  sectionTitle: {
    fontSize: "1.5rem",
    fontWeight: "bold",
    marginBottom: "1.5rem",
    color: "#4b3b34",
  },
  actionsGrid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))",
    gap: "2rem",
    marginBottom: "3rem",
  },
  actionCard: {
    backgroundColor: "#fff",
    borderRadius: "12px",
    boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
    padding: "2rem",
    display: "flex",
    flexDirection: "column",
    transition: "transform 0.2s ease, box-shadow 0.2s ease",
  },
  actionIcon: {
    color: "#8b6b5c",
    marginBottom: "1rem",
    display: "flex",
    justifyContent: "center",
  },
  actionTitle: {
    fontSize: "1.3rem",
    fontWeight: "600",
    marginBottom: "0.75rem",
    color: "#4b3b34",
  },
  actionDesc: {
    fontSize: "1.1rem",
    color: "#6a5b53",
    marginBottom: "1.5rem",
    lineHeight: "1.5",
  },
  actionBtn: {
    backgroundColor: "#8b6b5c",
    color: "#fff",
    padding: "0.75rem 1.5rem",
    borderRadius: "8px",
    border: "none",
    fontSize: "1rem",
    cursor: "pointer",
    fontWeight: "500",
    marginTop: "auto",
    transition: "background-color 0.3s ease",
    width: "100%",
    textAlign: "center",
    outline: "none",
    userSelect: "none"
  },
  recentActivity: {
    backgroundColor: "#fff",
    borderRadius: "12px",
    boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
    padding: "3rem",
    textAlign: "center",
    marginBottom: "3rem",
  },
  recentIcon: {
    width: "48px",
    height: "48px",
    margin: "0 auto 1.5rem",
    color: "#8b6b5c",
  },
  recentTitle: {
    fontSize: "1.4rem",
    fontWeight: "600",
    marginBottom: "1rem",
    color: "#4b3b34",
  },
  recentText: {
    fontSize: "1rem",
    color: "#6a5b53",
    marginBottom: "2rem",
    lineHeight: "1.6",
    maxWidth: "500px",
    margin: "0 auto 2rem",
  },
  recentBtn: {
    backgroundColor: "#8b6b5c",
    color: "#fff",
    padding: "1rem 2rem",
    borderRadius: "8px",
    border: "none",
    cursor: "pointer",
    fontSize: "1rem",
    fontWeight: "500",
    transition: "background-color 0.2s ease",
  },
  matchesContainer: {
    maxHeight: "600px",
    overflowY: "auto",
    paddingRight: "1rem",
  },
  myMatchesContainer: {
    maxHeight: "600px",
    overflowY: "auto",
    paddingRight: "1rem",
  },
  matchesGrid: {
    display: "flex",
    gap: "1.5rem",
    overflowX: "auto",
    overflowY: "hidden",
    paddingBottom: "1rem",
    scrollBehavior: "smooth",
    scrollbarWidth: "thin",
    scrollbarColor: "#8b6b5c #f5ede6",
    WebkitOverflowScrolling: "touch",
  },
  matchCard: {
    backgroundColor: "#fff",
    borderRadius: "12px",
    boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
    padding: "1.5rem",
    transition: "transform 0.2s ease, box-shadow 0.2s ease",
    minWidth: "350px",
    maxWidth: "350px",
    flexShrink: 0,
  },
  matchHeader: {
    display: "flex",
    alignItems: "center",
    gap: "1rem",
    marginBottom: "1rem",
  },
  avatar: {
    width: "50px",
    height: "50px",
    borderRadius: "50%",
    backgroundColor: "#8b6b5c",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    color: "#fff",
    fontWeight: "bold",
    fontSize: "1.2rem",
  },
  matchName: {
    fontSize: "1.2rem",
    fontWeight: "600",
    color: "#4b3b34",
  },
  matchSkills: {
    marginBottom: "1rem",
  },
  skillLabel: {
    fontSize: "0.9rem",
    fontWeight: "600",
    color: "#6a5b53",
    marginBottom: "0.25rem",
  },
  skillTags: {
    display: "flex",
    flexWrap: "wrap",
    gap: "0.5rem",
    marginBottom: "0.75rem",
  },
  skillTag: {
    backgroundColor: "#f5ede6",
    color: "#4b3b34",
    padding: "0.25rem 0.75rem",
    borderRadius: "6px",
    fontSize: "0.85rem",
  },
  sendRequestBtn: {
    backgroundColor: "#8b6b5c",
    color: "#fff",
    border: "none",
    padding: "0.75rem 1.5rem",
    borderRadius: "8px",
    cursor: "pointer",
    width: "100%",
    fontSize: "1rem",
    fontWeight: "500",
    display: "flex",
